package com.pablo.controlgastos;
import android.app.*;import android.content.*;import android.database.Cursor;import android.graphics.Color;import android.os.Bundle;import android.text.InputType;import android.widget.*;import java.util.*;import java.util.regex.*;import javax.mail.*;import javax.mail.search.*;
public class CreditCardsActivity extends Activity{
 LinearLayout list;CreditCardDb db;android.content.SharedPreferences p;int BG,TEXT,CARD,MUTED;
 public void onCreate(Bundle b){ThemePrefs.applyBaseTheme(this);super.onCreate(b);db=new CreditCardDb(this);p=getSharedPreferences("card_email",0);boolean l=ThemePrefs.isLight(this);BG=l?0xfff6f8f9:0xff0b1218;TEXT=l?0xff1f262c:0xfff2f5f7;CARD=l?Color.WHITE:0xff162029;MUTED=l?0xff5f6970:0xff9ea9b2;build();}
 TextView t(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(TEXT);v.setPadding(18,14,18,14);return v;}Button btn(String s){Button x=new Button(this);x.setText(s);x.setAllCaps(false);return x;}
 void build(){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(20,55,20,20);r.setBackgroundColor(BG);r.addView(t("Tarjetas de crédito",26));LinearLayout a=new LinearLayout(this);Button cfg=btn("⚙ Correo"),sync=btn("↻ Leer estados");a.addView(cfg,new LinearLayout.LayoutParams(0,-2,1));a.addView(sync,new LinearLayout.LayoutParams(0,-2,1));r.addView(a);cfg.setOnClickListener(v->config());sync.setOnClickListener(v->sync());ScrollView sc=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);sc.addView(list);r.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);refresh();}
 void refresh(){list.removeAllViews();Cursor c=db.getReadableDatabase().rawQuery("SELECT c.name,c.last4,s.id,s.close_date,s.due_date,s.total,s.currency FROM cards c LEFT JOIN statements s ON s.card_id=c.id AND s.id=(SELECT MAX(x.id) FROM statements x WHERE x.card_id=c.id) ORDER BY c.id",null);while(c.moveToNext()){long sid=c.isNull(2)?-1:c.getLong(2);String name=c.getString(0),last=c.getString(1);double total=sid<0?0:c.getDouble(5);String z=name+" •••• "+last+(sid<0?"\nSin estado importado":"\nCierre: "+c.getString(3)+"   Vence: "+c.getString(4)+"\nPago contado: "+c.getString(6)+" "+String.format(Locale.US,"%.2f",total)+payment(total));TextView x=t(z,17);x.setBackgroundColor(CARD);x.setOnClickListener(v->{if(sid>0)statement(sid,name,last);});list.addView(x);}c.close();if(list.getChildCount()==0)list.addView(t("Todavía no hay tarjetas. Al leer un estado se agregará automáticamente.",15));}
 String payment(double total){boolean am=p.getBoolean("pay_amount",true),tx=p.getBoolean("pay_text",true);ExpenseDb e=new ExpenseDb(this);Cursor c=e.getReadableDatabase().rawQuery("SELECT amount,description FROM tx WHERE type='GASTO' ORDER BY ts DESC LIMIT 300",null);try{while(c.moveToNext()){String d=c.getString(1)==null?"":c.getString(1).toUpperCase(Locale.ROOT);if((!am||Math.abs(c.getDouble(0)-total)<=.01)&&(!tx||d.contains("PAGO TC")||d.contains("PAGO DE TARJETA")))return"\n✓ Pago de tarjeta identificado";}return"\nPago aún no identificado";}finally{c.close();e.close();}}
 String installmentInfo(String raw){if(raw==null)return"";Matcher m=Pattern.compile("(?i)CUOTA\\s*0*(\\d{1,2})/0*(\\d{1,2})").matcher(raw);if(!m.find())return raw;int cur=Integer.parseInt(m.group(1)),tot=Integer.parseInt(m.group(2)),left=Math.max(0,tot-cur);return"Cuota "+cur+" de "+tot+" · "+left+" restante"+(left==1?"":"s");}
 void statement(long sid,String name,String last){LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);TextView h=t("Cuotas y montos del estado\nLa app prioriza la cuota actual, el total de cuotas, cuántas quedan y el monto de cada cuota.",14);h.setTextColor(MUTED);f.addView(h);Cursor c=db.getReadableDatabase().rawQuery("SELECT tx_date,description,installment,amount,currency FROM installments WHERE statement_id=? ORDER BY id",new String[]{""+sid});while(c.moveToNext()){String inst=installmentInfo(c.getString(2));String line=c.getString(1)+"\n"+(inst.isEmpty()?"Compra sin cuota detectada":inst)+"\nMonto: "+c.getString(4)+" "+String.format(Locale.US,"%.2f",c.getDouble(3))+"   ·   "+c.getString(0);TextView v=t(line,15);v.setBackgroundColor(CARD);f.addView(v,new LinearLayout.LayoutParams(-1,-2));}c.close();ScrollView s=new ScrollView(this);s.addView(f);new AlertDialog.Builder(this).setTitle(name+" •••• "+last+" — cuotas").setView(s).setPositiveButton("Cerrar",null).show();}
 EditText edit(String h,String v){EditText x=new EditText(this);x.setHint(h);x.setText(v);x.setTextColor(TEXT);x.setHintTextColor(MUTED);return x;}
 void config(){LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);EditText email=edit("Correo",p.getString("email","")),pass=edit("Contraseña de aplicación",SecretStore.get(this)),host=edit("Servidor IMAP",p.getString("host","imap.gmail.com"));pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);Switch amount=new Switch(this);amount.setText("Identificar pago por monto coincidente");amount.setChecked(p.getBoolean("pay_amount",true));Switch text=new Switch(this);text.setText("Identificar pago porque dice PAGO TC");text.setChecked(p.getBoolean("pay_text",true));f.addView(email);f.addView(pass);f.addView(host);f.addView(amount);f.addView(text);new AlertDialog.Builder(this).setTitle("Correo de estados de cuenta").setMessage("Para Gmail usá una contraseña de aplicación. Se cifra con Android Keystore. Solo se buscan correos de SistarBanc con asunto Estado de cuenta. Los switches solo identifican el gasto del pago de la tarjeta; no afectan la lectura de compras y cuotas.").setView(f).setPositiveButton("Guardar",(d,w)->{if(!amount.isChecked()&&!text.isChecked()){Toast.makeText(this,"Activá al menos una forma de identificar el pago",Toast.LENGTH_LONG).show();return;}p.edit().putString("email",email.getText().toString().trim()).putString("host",host.getText().toString().trim()).putBoolean("pay_amount",amount.isChecked()).putBoolean("pay_text",text.isChecked()).remove("pass").apply();SecretStore.put(this,pass.getText().toString());refresh();}).setNegativeButton("Cancelar",null).show();}
 void sync(){String email=p.getString("email",""),pass=SecretStore.get(this);if(email.isEmpty()||pass.isEmpty()){config();return;}Toast.makeText(this,"Buscando estados de cuenta…",Toast.LENGTH_SHORT).show();new Thread(()->{int n=0;try{Properties q=new Properties();q.put("mail.store.protocol","imaps");Session se=Session.getInstance(q);Store st=se.getStore("imaps");st.connect(p.getString("host","imap.gmail.com"),email,pass);Folder in=st.getFolder("INBOX");in.open(Folder.READ_ONLY);javax.mail.Message[] ms=in.search(new AndTerm(new FromStringTerm("sistarbanc"),new SubjectTerm("Estado de cuenta")));for(int i=Math.max(0,ms.length-24);i<ms.length;i++)if(parse(body(ms[i])))n++;in.close(false);st.close();int done=n;runOnUiThread(()->{refresh();Toast.makeText(this,"Estados leídos: "+done,Toast.LENGTH_LONG).show();});}catch(Exception ex){runOnUiThread(()->new AlertDialog.Builder(this).setTitle("No se pudo leer el correo").setMessage(ex.getMessage()+"\n\nEn Gmail normalmente se necesita una contraseña de aplicación.").setPositiveButton("Aceptar",null).show());}}).start();}
 String body(Part p)throws Exception{Object o=p.getContent();if(o instanceof String)return(String)o;if(o instanceof Multipart){Multipart m=(Multipart)o;StringBuilder s=new StringBuilder();for(int i=0;i<m.getCount();i++)s.append(body(m.getBodyPart(i))).append('\n');return s.toString();}return"";}String clean(String h){return h.replaceAll("(?is)<style.*?</style>"," ").replaceAll("(?is)<[^>]+>"," ").replace("&nbsp;"," ").replace("&amp;","&").replaceAll("\\s+"," ");}
 boolean parse(String raw){String s=clean(raw);Matcher card=Pattern.compile("(?i)TARJETA\\s*(?:No)?[: ]+\\s*([0-9]{4,6})\\*+([0-9]{4})").matcher(s);if(!card.find())return false;long cid=db.card("BROU MasterCard",card.group(2));String close=find(s,"(?i)Fecha de cierre[: ]+([0-9/]+)"),due=find(s,"(?i)Vencimiento actual[: ]+([0-9/]+)");double total=num(find(s,"(?i)SALDO CONTADO\\s+([0-9.,]+)"));long sid=db.statement(cid,close,due,total,"UYU");db.clearItems(sid);Matcher row=Pattern.compile("([0-3]?\\d/[01]?\\d/\\d{2,4})\\s+(.{3,80}?)\\s+([0-9][0-9.,]*)\\s+(?:\\.00|0[.,]00)",Pattern.CASE_INSENSITIVE).matcher(s);while(row.find()){String desc=row.group(2).trim();if(desc.matches("(?i).*(SALDO ANTERIOR|PAGOS|TOTAL TARJETA).*"))continue;String inst=find(desc,"(?i)(CUOTA\\s*0*\\d{1,2}/0*\\d{1,2})");db.item(sid,row.group(1),desc,inst,num(row.group(3)),"UYU");}return true;}
 String find(String s,String r){Matcher m=Pattern.compile(r).matcher(s);return m.find()?m.group(1):"";}double num(String x){try{String q=x.trim();int c=q.lastIndexOf(','),d=q.lastIndexOf('.');if(c>=0&&d>=0)q=d>c?q.replace(",",""):q.replace(".","").replace(',','.');else if(c>=0)q=(q.length()-c-1==2)?q.replace(',','.'):q.replace(",","");return Double.parseDouble(q);}catch(Exception e){return 0;}}
}